import{_ as s,o as n,c as e,a0 as t}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"Os","description":"","frontmatter":{},"headers":[],"relativePath":"modules/syntax/os.md","filePath":"modules/syntax/os.md"}'),i={name:"modules/syntax/os.md"};function p(o,a,d,l,r,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="os" tabindex="-1">Os <a class="header-anchor" href="#os" aria-label="Permalink to &quot;Os&quot;">​</a></h1><p>Modul <code>os</code> menyediakan fungsi untuk berinteraksi dengan sistem operasi.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import os from rupa</span></span></code></pre></div><h2 id="apa-yang-bisa-dilakukan" tabindex="-1">Apa yang bisa dilakukan? <a class="header-anchor" href="#apa-yang-bisa-dilakukan" aria-label="Permalink to &quot;Apa yang bisa dilakukan?&quot;">​</a></h2><h3 id="mendapatkan-working-directory" tabindex="-1">Mendapatkan working directory <a class="header-anchor" href="#mendapatkan-working-directory" aria-label="Permalink to &quot;Mendapatkan working directory&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cwd = os.getcwd()</span></span>
<span class="line"><span>print(cwd)</span></span>
<span class="line"><span>// /home/user/project</span></span></code></pre></div><h3 id="mengganti-working-directory" tabindex="-1">Mengganti working directory <a class="header-anchor" href="#mengganti-working-directory" aria-label="Permalink to &quot;Mengganti working directory&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>os.chdir(&quot;/tmp&quot;)</span></span>
<span class="line"><span>print(os.getcwd())</span></span>
<span class="line"><span>// /tmp</span></span></code></pre></div><h3 id="menjalankan-command-sistem" tabindex="-1">Menjalankan command sistem <a class="header-anchor" href="#menjalankan-command-sistem" aria-label="Permalink to &quot;Menjalankan command sistem&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>output = os.exec(&quot;ls -la&quot;)</span></span>
<span class="line"><span>print(output)</span></span></code></pre></div><p><code>os.exec()</code> mengembalikan output dari command sebagai string.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Cek versi node</span></span>
<span class="line"><span>version = os.exec(&quot;node --version&quot;)</span></span>
<span class="line"><span>print(version)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Cek disk usage</span></span>
<span class="line"><span>disk = os.exec(&quot;df -h /&quot;)</span></span>
<span class="line"><span>print(disk)</span></span></code></pre></div><h3 id="membaca-environment-variable" tabindex="-1">Membaca environment variable <a class="header-anchor" href="#membaca-environment-variable" aria-label="Permalink to &quot;Membaca environment variable&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user = os.getenv(&quot;USER&quot;)</span></span>
<span class="line"><span>print(user)</span></span>
<span class="line"><span>// aidomx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Jika variable tidak ada, mengembalikan null</span></span>
<span class="line"><span>home = os.getenv(&quot;HOME&quot;)</span></span>
<span class="line"><span>print(home)</span></span>
<span class="line"><span>// /home/aidomx</span></span></code></pre></div><h3 id="bekerja-dengan-file-dan-directory" tabindex="-1">Bekerja dengan file dan directory <a class="header-anchor" href="#bekerja-dengan-file-dan-directory" aria-label="Permalink to &quot;Bekerja dengan file dan directory&quot;">​</a></h3><h4 id="membuat-directory" tabindex="-1">Membuat directory <a class="header-anchor" href="#membuat-directory" aria-label="Permalink to &quot;Membuat directory&quot;">​</a></h4><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>os.mkdir(&quot;my-folder&quot;)</span></span>
<span class="line"><span>print(os.path.exists(&quot;my-folder&quot;))</span></span>
<span class="line"><span>// true</span></span></code></pre></div><h4 id="cek-keberadaan-file-directory" tabindex="-1">Cek keberadaan file/directory <a class="header-anchor" href="#cek-keberadaan-file-directory" aria-label="Permalink to &quot;Cek keberadaan file/directory&quot;">​</a></h4><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(os.path.exists(&quot;/etc/passwd&quot;))</span></span>
<span class="line"><span>// true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(os.path.exists(&quot;file-tidak-ada&quot;))</span></span>
<span class="line"><span>// false</span></span></code></pre></div><h4 id="list-isi-directory" tabindex="-1">List isi directory <a class="header-anchor" href="#list-isi-directory" aria-label="Permalink to &quot;List isi directory&quot;">​</a></h4><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>files = os.listdir(&quot;.&quot;)</span></span>
<span class="line"><span>print(files)</span></span>
<span class="line"><span>// [src, bin, lib, ...]</span></span></code></pre></div><h4 id="rename-file" tabindex="-1">Rename file <a class="header-anchor" href="#rename-file" aria-label="Permalink to &quot;Rename file&quot;">​</a></h4><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>os.rename(&quot;old-name.txt&quot;, &quot;new-name.txt&quot;)</span></span></code></pre></div><h4 id="hapus-file" tabindex="-1">Hapus file <a class="header-anchor" href="#hapus-file" aria-label="Permalink to &quot;Hapus file&quot;">​</a></h4><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>os.remove(&quot;file-yang-ingin-dihapus.txt&quot;)</span></span></code></pre></div><h3 id="informasi-sistem" tabindex="-1">Informasi sistem <a class="header-anchor" href="#informasi-sistem" aria-label="Permalink to &quot;Informasi sistem&quot;">​</a></h3><p>Tanpa parameter, <code>os.info()</code> mengembalikan object dengan semua informasi:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>info = os.info()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(info.sysname)    // Linux</span></span>
<span class="line"><span>print(info.machine)    // x86_64</span></span>
<span class="line"><span>print(info.release)    // 6.1.0-generic</span></span>
<span class="line"><span>print(info.user)       // aidomx</span></span>
<span class="line"><span>print(info.hostname)   // mycomputer</span></span></code></pre></div><p>Dengan parameter, <code>os.info(key)</code> mengembalikan string tertentu:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(os.info(&quot;machine&quot;))</span></span>
<span class="line"><span>// x86_64</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(os.info(&quot;user&quot;))</span></span>
<span class="line"><span>// aidomx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(os.info(&quot;sysname&quot;))</span></span>
<span class="line"><span>// Linux</span></span></code></pre></div><p>Tersedia keys: <code>sysname</code>, <code>nodename</code>, <code>release</code>, <code>version</code>, <code>machine</code>, <code>user</code>, <code>hostname</code>.</p><h3 id="keluar-dari-program" tabindex="-1">Keluar dari program <a class="header-anchor" href="#keluar-dari-program" aria-label="Permalink to &quot;Keluar dari program&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>os.exit(0)</span></span></code></pre></div><h2 id="ringkasan" tabindex="-1">Ringkasan <a class="header-anchor" href="#ringkasan" aria-label="Permalink to &quot;Ringkasan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fungsi</th><th>Parameter</th><th>Return</th><th>Deskripsi</th></tr></thead><tbody><tr><td><code>getcwd()</code></td><td>-</td><td>string</td><td>Working directory</td></tr><tr><td><code>chdir(path)</code></td><td>string</td><td>bool</td><td>Ganti directory</td></tr><tr><td><code>listdir(path)</code></td><td>string</td><td>array</td><td>List isi directory</td></tr><tr><td><code>getenv(key)</code></td><td>string</td><td>string/null</td><td>Baca env variable</td></tr><tr><td><code>exec(cmd)</code></td><td>string</td><td>string</td><td>Jalankan command</td></tr><tr><td><code>mkdir(path)</code></td><td>string</td><td>bool</td><td>Buat directory</td></tr><tr><td><code>remove(path)</code></td><td>string</td><td>bool</td><td>Hapus file</td></tr><tr><td><code>rename(old, new)</code></td><td>string×2</td><td>bool</td><td>Rename file</td></tr><tr><td><code>info(key?)</code></td><td>string (opt)</td><td>object/string</td><td>Info sistem</td></tr><tr><td><code>exit(code)</code></td><td>int</td><td>-</td><td>Keluar program</td></tr></tbody></table><h3 id="os-path" tabindex="-1">os.path <a class="header-anchor" href="#os-path" aria-label="Permalink to &quot;os.path&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fungsi</th><th>Parameter</th><th>Return</th><th>Deskripsi</th></tr></thead><tbody><tr><td><code>exists(path)</code></td><td>string</td><td>bool</td><td>Cek keberadaan</td></tr></tbody></table><h2 id="contoh" tabindex="-1">Contoh <a class="header-anchor" href="#contoh" aria-label="Permalink to &quot;Contoh&quot;">​</a></h2><h3 id="backup-file" tabindex="-1">Backup file <a class="header-anchor" href="#backup-file" aria-label="Permalink to &quot;Backup file&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import os from rupa</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Cek file ada</span></span>
<span class="line"><span>if os.path.exists(&quot;config.txt&quot;):</span></span>
<span class="line"><span>    // Rename ke backup</span></span>
<span class="line"><span>    os.rename(&quot;config.txt&quot;, &quot;config.txt.bak&quot;)</span></span>
<span class="line"><span>    print(&quot;File backed up&quot;)</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    print(&quot;File not found&quot;)</span></span></code></pre></div><h3 id="setup-project" tabindex="-1">Setup project <a class="header-anchor" href="#setup-project" aria-label="Permalink to &quot;Setup project&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import os from rupa</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Buat struktur folder</span></span>
<span class="line"><span>os.mkdir(&quot;src&quot;)</span></span>
<span class="line"><span>os.mkdir(&quot;tests&quot;)</span></span>
<span class="line"><span>os.mkdir(&quot;docs&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Cek hasil</span></span>
<span class="line"><span>print(os.listdir(&quot;.&quot;))</span></span>
<span class="line"><span>// [src, tests, docs, ...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(&quot;Project structure created!&quot;)</span></span></code></pre></div><h3 id="cek-environment" tabindex="-1">Cek environment <a class="header-anchor" href="#cek-environment" aria-label="Permalink to &quot;Cek environment&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import os from rupa</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(&quot;User:&quot;, os.getenv(&quot;USER&quot;))</span></span>
<span class="line"><span>print(&quot;Home:&quot;, os.getenv(&quot;HOME&quot;))</span></span>
<span class="line"><span>print(&quot;Shell:&quot;, os.getenv(&quot;SHELL&quot;))</span></span>
<span class="line"><span>print(&quot;Platform:&quot;, os.info(&quot;sysname&quot;))</span></span>
<span class="line"><span>print(&quot;Architecture:&quot;, os.info(&quot;machine&quot;))</span></span></code></pre></div>`,44)])])}const m=s(i,[["render",p]]);export{h as __pageData,m as default};
